'use strict';
let db;let currentBranch=null;let resultIds=[];let resultNotice='';let blockedIngredientIds=[];let comparisonIds=[];let tmQuery='';
const main=document.getElementById('main');
const escapeHtml=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHtml;
const find=(collection,id)=>db[collection].find(x=>x.id===id);
const crumbs=(label)=>`<div class="breadcrumb"><a href="#home">ホーム</a><span>/</span><span>${E(label)}</span></div>`;
const a=(url,label,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="${E(url)}">${E(label)}</a>`;
const external=(url,label)=>db?.unavailable_external_urls?.includes(url)?`<span class="metadata">${E(label)}（現在リンク先を利用できません）</span>`:/^https:\/\//.test(url||'')?`<a href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(label)}（別タブ）</a>`:'';
const researchLabels={guideline:'学会ガイドライン',professional_guidance:'皮膚科専門団体の解説',rct_abstract:'比較試験・抄録確認',manufacturer:'メーカー公式情報',regulatory:'公的通知',api_documentation:'公式API資料',terms:'利用規約'};
const labels={guidance:'専門団体の解説',limited_human:'限定した製剤での比較試験',treatment_context:'医療での使用を含む研究',manufacturer_only:'メーカー公式表示'};
function display(html,title){main.innerHTML=linkIngredientNames(html);document.title=`${title} | 美容液逆引きナビ`;main.focus({preventScroll:true});window.scrollTo(0,0);}
function home(){display(`<div class="home-layout"><section><div class="eyebrow">SKINCARE INDEX</div><h1>肌をきれいに見せたい。<br>商品選びは、そこから。</h1><p class="sub">近い悩みをひとつ選んでください。<br>うまく説明できないときも、そのまま進めます。</p><div class="concern-grid">${db.conditions.filter(c=>c.show_in_navigation!==false).map((c,i)=>`<a class="concern" href="#${'concern/'+c.id}"><span class="index">${String(i+1).padStart(2,'0')}</span><span class="concern-label">${E(c.name_ja)}</span>${concernArt(c.id)}</a>`).join('')}</div></section><aside class="side"><div class="eyebrow">INGREDIENTS</div><h2>名前を知っている<br>成分から探す</h2><p>ナイアシンアミド、アゼライン酸。気になった成分の根拠と注意を、先に確認できます。</p><a href="#ingredients">成分一覧を見る</a><small>成分の研究が、そのまま商品の効果を示すわけではありません。</small></aside></div><div class="flow"><span><b>01 悩みを選ぶ</b>そのまま商品を見る</span><span><b>02 成分から商品へ</b>パッケージと配合成分で比べる</span><span><b>03 購入ページへ</b>楽天で商品を確認</span></div>`,'悩みから探す');}
function concern(id){const c=find('conditions',id);if(!c)return missing();if(c.direct_branch_id){startBranch(c.direct_branch_id);return;}const q=find('questions',c.question_id);display(`${crumbs(c.name_ja)}<section class="narrow"><div class="step">見え方・状態を選択</div><div class="concern-heading">${concernArt(c.id)}<h1>${E(c.name_ja)}</h1></div><p>${E(q.prompt)}</p><p class="sub">見た目だけで原因や病名を判断するものではありません。</p><div class="options">${q.options.map(o=>`<button class="option" data-branch="${o.branch_id}">${E(o.label)}</button>`).join('')}</div>${a('#home','悩みを選び直す',true)}</section>`,c.name_ja);main.querySelectorAll('[data-branch]').forEach(el=>el.onclick=()=>startBranch(el.dataset.branch));}
function initialBlocked(b){return ['sensitive','redness','dry'].includes(b.condition_id)?['retinol','salicylic','azelaic']:[];}
function startBranch(id){const b=find('branches',id);if(!b)return missing();currentBranch=id;resultIds=[...b.ingredient_ids];resultNotice='';blockedIngredientIds=initialBlocked(b);if(b.followup){followup(b);return;}location.hash='result/'+id;if(location.hash==='#result/'+id)result(id);}
function followup(b){const f=find('followups',b.followup);const c=find('conditions',b.condition_id);display(`${crumbs(c.name_ja)}<section class="narrow"><div class="step">追加の確認 · この1問で終わります</div><h1>${E(f.prompt)}</h1><div class="options">${f.options.map(o=>`<button class="option" data-answer="${o.id}">${E(o.label)}</button>`).join('')}</div>${a('#concern/'+c.id,'状態を選び直す',true)}</section>`,'追加の確認');main.querySelectorAll('[data-answer]').forEach(el=>el.onclick=()=>answerFollowup(b.id,el.dataset.answer));}
function answerFollowup(id,answer){const b=find('branches',id),f=b&&find('followups',b.followup),o=f?.options.find(o=>o.id===answer);if(!o)throw new Error('選択肢を確認してください。');currentBranch=id;resultIds=[...b.ingredient_ids];resultNotice='';blockedIngredientIds=initialBlocked(b);if(o.action==='replace_basic'){resultIds=[...o.ingredient_ids];blockedIngredientIds=['retinol','salicylic','azelaic'];resultNotice='今回は刺激を伴う候補を控え、保湿の参考情報を表示します。刺激が続く場合は皮膚科へ相談してください。';}if(o.action==='remove'){blockedIngredientIds=[...o.ingredient_ids];resultIds=resultIds.filter(i=>!o.ingredient_ids.includes(i));resultNotice='レチノールを候補から外しました。';}location.hash='result/'+id;result(id);}
function result(id){const b=find('branches',id);if(!b)return missing();if(currentBranch!==id){currentBranch=id;resultIds=[...b.ingredient_ids];resultNotice='';blockedIngredientIds=initialBlocked(b);if(b.followup){followup(b);return;}}const c=find('conditions',b.condition_id);const consult=['consult','stop_consult'].includes(b.mode);display(`${crumbs(c.name_ja)}<section><div class="eyebrow">${consult?'CARE FIRST':'PRODUCT OPTIONS'}</div><h1>${consult?'まず、肌の状態を相談してください。':resultIds.length?'まず、成分を確認する':'この状態に対応する情報は登録されていません。'}</h1><p class="sub">${E(b.reason)}</p>${resultNotice?`<div class="notice warning">${E(resultNotice)}</div>`:''}${b.mode==='learn'&& !resultNotice?'<div class="notice warning">以下には医療で使われる成分の研究を含みます。日本の化粧品に、同じ治療効果があることを示していません。</div>':''}${consult?`<div class="notice warning"><p>${b.mode==='stop_consult'?'新しく使い始めた商品の使用を止め、症状が続く場合は皮膚科へ相談してください。':'痛み・炎症・変化がある場合は、美容商品の追加より原因の確認を優先してください。'}</p></div>${a('#medical','皮膚科の治療情報を見る')}`:`<div class="cards">${resultIds.map(i=>ingredientCard(find('ingredients',i))).join('')}</div>`}<details class="section"><summary>成分の根拠・注意を読む</summary>${evidenceBlocks(b.evidence_ids)}</details><div class="actions">${a('#concern/'+c.id,'状態を選び直す',true)}${a('#home','別の悩みを調べる',true)}</div></section>`,c.name_ja+'の参考情報');}
function productResults(b){
 const targets=resultIds;
 const candidates=db.products.filter(p=>['cosmetic','quasi_drug'].includes(p.regulatory_class)&&db.product_ingredients.some(pi=>pi.product_id===p.id&&targets.includes(pi.ingredient_id))&&!db.product_ingredients.some(pi=>pi.product_id===p.id&&blockedIngredientIds.includes(pi.ingredient_id)));
 const list=candidates.filter(p=>{
  const hasRetinol=db.product_ingredients.some(pi=>pi.product_id===p.id&&pi.ingredient_id==='retinol');
  if(hasRetinol&&b.condition_id!=='lines')return false;
  if(b.mode==='learn'&&!resultNotice)return false;
  if(b.condition_id==='oil'&&!resultNotice)return false;
  return true;
 });
 if(!list.length)return '<div class="empty"><h2>この状態への商品候補は、まだ絞り込めません。</h2><p>成分が配合されているだけでは、目的に合う商品と判断できません。確認できる情報を揃えてから候補を増やします。</p></div>';
 return `<p class="metadata">確認済みの登録商品から抽出しています。相性や効果の順位ではありません。</p><div class="cards">${list.map(p=>{
 const matched=db.product_ingredients.filter(pi=>pi.product_id===p.id&&targets.includes(pi.ingredient_id));
 return `<article class="card"><span class="badge">${p.regulatory_class==='cosmetic'?'化粧品':'医薬部外品'}</span><h2>${E(p.name)}</h2><p>${p.size_value}${E(p.size_unit)} · ${E(p.variant)}</p><p><b>候補に含めた理由</b><br>${E(matched.map(pi=>pi.label_name+'（'+pi.purpose+'）').join('、'))}を公式情報で確認。</p><p class="metadata">商品自体の比較試験・個人への相性評価：未確認</p><div class="actions">${a('#product/'+p.id,'注意・商品詳細を見る',true)}${purchaseButton(p.id)}</div></article>`;
 }).join('')}</div>`;
}
function ingredientCard(i){return `<article class="card"><span class="badge">${E(labels[i.evidence_label]||'参考情報')}</span><h2>${E(i.name_ja)}</h2>${i.card_studies?`<div class="ingredient-studies">${i.card_studies.map(r=>`<p><b>${E(r.topic)}</b><br>${E(r.finding)} ${external(find('evidence',r.source_id)?.url,'出典')}</p>`).join('')}<p class="sub"><b>分かっていないこと・限界</b><br>${E(i.card_limit)}</p></div>`:`<p class="sub">${E(i.role)}</p>`}<div class="actions">${a('#products/'+i.id,'この成分の配合商品を探す')}${a('#ingredient/'+i.id,'根拠・注意',true)}</div></article>`;}
function ingredients(){display(`${crumbs('成分から探す')}<div class="eyebrow">INGREDIENTS</div><h1>成分から探す</h1><p class="sub">成分名・別名から探せます。研究の根拠とメーカーの配合目的を区別し、ブランドを問わず配合商品へ進めます。</p><label for="search">成分名・別名</label><br><input class="search" id="search" type="search" placeholder="例：ナイアシンアミド、BHA" autocomplete="off"><p class="metadata" id="count" role="status"></p><div class="cards" id="ingredient-list"></div>`,'成分から探す');const input=main.querySelector('#search');const update=()=>{const term=input.value.normalize('NFKC').toLowerCase().trim();const rank=id=>{const n=(db.ingredient_display_priority||[]).indexOf(id);return n<0?999:n;};const list=db.ingredients.filter(i=>!(db.excluded_discovery_ingredient_ids||[]).includes(i.id)).filter(i=>[i.name_ja,...i.aliases].some(v=>v.normalize('NFKC').toLowerCase().includes(term))).sort((a,b)=>rank(a.id)-rank(b.id));main.querySelector('#count').textContent=list.length+'成分';main.querySelector('#ingredient-list').innerHTML=list.length?list.map(ingredientCard).join(''):'<p class="empty">一致する成分はまだ登録されていません。</p>';};input.oninput=update;update();}
function evidenceBlocks(ids){return ids.map(id=>{const e=find('evidence',id);return e?`<article class="research"><span class="badge">${E(researchLabels[e.kind]||'参考情報')}</span><h3>${E(e.title)}</h3><p>${E(e.summary)}</p><p class="sub">限界：${E(e.limitations)}</p><p class="metadata">参照確認：${E(e.checked_at)}</p>${external(e.url,'出典を開く')}</article>`:'';}).join('');}
function ingredient(id){const i=find('ingredients',id);if(!i||(db.excluded_discovery_ingredient_ids||[]).includes(id))return missing();display(`${crumbs('成分から探す')}<section class="narrow"><span class="badge">${E(labels[i.evidence_label])}</span><h1>${E(i.name_ja)}</h1><p class="sub">${E(i.aliases.join(' / '))}</p><div class="notice"><p>成分を含む研究と、購入できる商品自体の効果は別です。濃度・処方・対象が異なる結果を、そのまま商品に当てはめません。</p></div><div class="section"><h2>使用前に確認したいこと</h2><ul>${i.cautions.map(t=>`<li>${E(t)}</li>`).join('')}</ul><p class="sub">異常が出たら使用を止め、製品の注意表示を確認してください。治療中の場合は、使っている製品について医療者に確認してください。</p></div><div class="actions">${a('#products/'+id,'配合されている商品を見る')}</div><div class="section"><h2>根拠と、その限界</h2>${evidenceBlocks(i.evidence_ids)}</div></section>`,i.name_ja);}
function purchaseButton(id){const o=db.offers.find(o=>o.product_id===id&&o.match_status==='name_size_variant_checked');if(!o){const p=find('products',id);if(p?.sales_channel==='clinic_only')return `<a class="button" href="${E(p.official_url)}" target="_blank" rel="noopener noreferrer">メーカーの商品情報を見る（別タブ）</a><p class="metadata">病院・クリニック専売品</p>`;return p?`<a class="button" href="https://search.rakuten.co.jp/search/mall/${encodeURIComponent(p.name+' '+p.size_value+p.size_unit)}/" target="_blank" rel="noopener noreferrer">楽天でこの商品を探す（別タブ）</a><p class="metadata">楽天の検索結果へ進みます。容量・本体／詰替は販売ページで確認してください。</p>`:'';}const url=o.is_affiliate?o.affiliate_url:o.item_url;if(!/^https:\/\//.test(url||''))return '';return `<a class="button" href="${E(url)}" target="_blank" rel="noopener noreferrer${o.is_affiliate?' sponsored':''}">楽天で見る（別タブ）</a>${o.is_affiliate?'<p class="metadata">広告・アフィリエイトリンク</p>':''}`;}
function productList(id,filter='all'){const i=find('ingredients',id);if(!i||(db.excluded_discovery_ingredient_ids||[]).includes(id))return missing();const matches=db.products.filter(p=>['cosmetic','quasi_drug'].includes(p.regulatory_class)&&db.product_ingredients.some(pi=>pi.product_id===p.id&&pi.ingredient_id===id));const overseas=(db.international_catalog||[]).filter(p=>filter==='all'&&p.ingredient_ids.includes(id)&&!p.ingredient_ids.some(i=>blockedIngredientIds.includes(i)));const tm=(db.tunemakers_catalog||[]).filter(p=>!blockedIngredientIds.length&&p.ingredient_index_id===id&&(filter==='all'||p.regulatory_class===filter));const list=matches.sort((a,b)=>a.brand.localeCompare(b.brand,'ja')||a.name.localeCompare(b.name,'ja')).filter(p=>(filter==='all'||p.regulatory_class===filter)&&!db.product_ingredients.some(pi=>pi.product_id===p.id&&blockedIngredientIds.includes(pi.ingredient_id)));display(`${crumbs(i.name_ja+'の配合商品')}<h1>${E(i.name_ja)}の配合商品</h1>${id==='tranexamic'?'<div class="notice warning">国内の外用医薬部外品と海外の商品情報を分けて表示します。肝斑の治療薬とは区別しています。国内医薬部外品の美白は、メラニンの生成を抑え、しみ・そばかすを防ぐ意味です。</div>':''}<p class="sub">メーカー公式情報で確認した商品を掲載しています。商品ごとに確認した配合目的を掲載します。成分の研究結果を、掲載商品の効能として表示しません。</p><p class="metadata">${list.length+tm.length}商品 · 公式配合情報を確認した商品を掲載。ブランド名順で表示。効果・人気・広告報酬による順位ではありません。</p><div class="toggle" aria-label="商品の区分">${[['all','すべて'],['cosmetic','化粧品'],['quasi_drug','医薬部外品']].map(([key,label])=>`<button data-filter="${key}" aria-pressed="${key===filter}">${label}</button>`).join('')}</div>${list.length||tm.length?`<div class="cards">${list.map(p=>`<article class="card">${p.image_url?`<img class="product-package" src="${E(p.image_url)}" alt="${E(p.name)}のパッケージ" loading="lazy" referrerpolicy="no-referrer">`: ''}<span class="badge">${p.regulatory_class==='quasi_drug'?'医薬部外品':'化粧品'}</span><h2>${E(p.name)}</h2>${p.product_type?`<p class="metadata">${E(p.product_type)}</p>`:''}<p>${E(p.brand)} · ${p.size_value}${E(p.size_unit)} · ${E(p.variant)}</p><p class="metadata">${E(db.product_ingredients.filter(pi=>pi.product_id===p.id&&pi.ingredient_id===id).map(pi=>pi.label_name+"（"+pi.purpose+"）").join("、"))}</p><div class="actions">${purchaseButton(p.id)}${a('#product/'+p.id,'成分・商品詳細',true)}</div></article>`).join('')}${tm.map(tmIngredientProductCard).join('')}</div>`:'<div class="empty"><h2>確認済みの商品はまだありません。</h2><p>商品情報の照合が完了したものから追加します。</p></div>'}${(db.exploration_catalog||[]).some(p=>p.ingredient_ids.includes(id))?`<section class="section"><h2>ボディ・頭皮用の商品</h2><p class="sub">顔用の候補とは使用部位が異なります。</p><div class="cards">${db.exploration_catalog.filter(p=>p.ingredient_ids.includes(id)).map(explorationCard).join('')}</div></section>`:''}${overseas.length?`<section class="section"><h2>海外メーカーの掲載商品</h2><p class="sub">メーカーの商品表記を確認した索引です。国内向けの製品区分・処方・販売先は未照合のため、公式情報へ案内します。数字はメーカー表記で、効果の順位ではありません。</p><div class="cards">${overseas.map(internationalCard).join('')}</div></section>`:''}<div class="actions">${a('#ingredient/'+id,'成分の根拠に戻る',true)}</div>`,'配合商品');main.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>productList(id,el.dataset.filter));}
function product(id){const p=find('products',id);if(!p||p.regulatory_class==='drug')return missing();const rows=db.product_ingredients.filter(x=>x.product_id===id&&!(db.excluded_discovery_ingredient_ids||[]).includes(x.ingredient_id));display(`${crumbs('商品情報')}<section class="narrow"><span class="badge">${p.regulatory_class==='quasi_drug'?'医薬部外品':'化粧品'}</span><h1>${E(p.name)}</h1><p>${E(p.brand)} · ${p.size_value}${E(p.sizeUnit||p.size_unit)} · ${E(p.variant)}</p><div class="actions">${purchaseButton(p.id)}</div><dl class="details"><dt>メーカー</dt><dd>${E(p.manufacturer)}</dd><dt>公式の表示</dt><dd>${E(p.approved_claims.join('、'))}</dd><dt>情報確認日</dt><dd>${E(p.source_checked_at)}</dd><dt>JAN</dt><dd>${E(p.jan||'メーカー公式で未確認')}</dd></dl><div class="section"><h2>確認した成分と配合目的</h2>${rows.map(r=>`<article class="research"><h3>${E(r.label_name)}</h3><p>${r.role==='active'?'有効成分':'その他の成分'} · ${E(r.purpose)}</p><p class="metadata">${r.concentration_percent!=null?"配合量："+E(r.concentration_percent)+"%（メーカー公開値）":"配合量：非開示"}</p><a href="#ingredient/${r.ingredient_id}">この成分の情報を見る</a></article>`).join('')}</div><div class="notice"><p>これは確認した成分の抜粋です。全成分はメーカー公式ページでご確認ください。</p></div><div class="section"><h2>使用前に確認すること</h2><ul>${(p.product_cautions||[]).map(t=>`<li>${E(t)}</li>`).join('')}</ul></div>${external(p.official_url,'メーカー公式で確認する')}<div class="section"><h2>販売先を確認する</h2><p class="sub">確認した購入ページへのリンクを掲載します。</p>${a('#sellers/'+id,'購入先を見る')}</div></section>`,'商品情報');}
function sellers(id){const p=find('products',id);if(!p||p.regulatory_class==='drug')return missing();const links=db.offers.filter(o=>o.product_id===id&&o.match_status==='name_size_variant_checked');display(`${crumbs('購入先')}<h1>${E(p.name)}の購入先</h1><p>${p.size_value}${E(p.size_unit)} · ${E(p.variant)}</p>${links.length?`<div class="cards">${links.map(o=>{const seller=find('sellers',o.seller_id);return `<article class="card"><span class="badge">楽天市場</span><h2>${E(seller.name)}</h2><p class="metadata">リンク確認：${E(o.checked_at)}</p>${o.is_affiliate?'<p class="metadata">広告・アフィリエイトリンク</p>':''}${external(o.is_affiliate?o.affiliate_url:o.item_url,'楽天で購入ページを見る')}</article>`;}).join('')}</div><p class="sub">容量・本体／詰替・商品名をリンク先でご確認ください。店舗の認定や品質を保証するものではありません。</p>`:'<div class="empty"><h2>購入リンクは登録されていません。</h2></div>'}${a('#product/'+id,'商品情報に戻る',true)}`,'購入先');}
function medical(){display(`${crumbs('医療の参考情報')}<section class="narrow"><h1>治療については、皮膚科で相談を。</h1><p>ニキビや続く赤みは、見た目が似ていても原因や必要な対応が異なります。このサイトの選択結果は診断ではありません。</p>${evidenceBlocks(['E01'])}<div class="notice">医薬品は化粧品の商品一覧や販売比較に掲載しません。</div>${a('#home','ホームに戻る',true)}</section>`,'医療の参考情報');}
function about(){display(`${crumbs('このサイトについて')}<section class="narrow"><h1>美容液逆引きナビについて</h1><p>悩みや成分名から、根拠と注意を確認して商品情報へ進むためのサイトです。回答をAIで判定する質問はありません。</p><h2>情報の扱い方</h2><p>化粧品、医薬部外品、医薬品を分けます。研究結果と当該商品の表示・効能を区別し、分からないことは分からないまま掲載します。</p><p>回答はこの画面内だけで使用します。妊娠関連の回答をURLやブラウザの保存領域に記録しません。外部のアクセス解析は導入していません。</p><h2 class="section">医学・美容の参考出典</h2>${evidenceBlocks(db.evidence.filter(e=>['E','L','P'].some(prefix=>e.id.startsWith(prefix))).map(e=>e.id))}</section>`,'このサイトについて');}
function missing(){display(`<h1>このページは見つかりません。</h1><p>悩みや成分を選び直してください。</p>${a('#home','ホームに戻る')}`,'ページが見つかりません');}
function route(){if(!db)return;const parts=location.hash.slice(1).split('/'),[r,id]=parts;switch(r){case '':case 'home':home();break;case 'concern':concern(id);break;case 'result':result(id);break;case 'ingredients':ingredients();break;case 'tunemakers':tunemakers();break;case 'discover':discover();break;case 'examples':exploration();break;case 'compare':compareTunemakers();break;case 'ingredient':ingredient(id);break;case 'products':productList(id);break;case 'product':product(id);break;case 'sellers':sellers(id);break;case 'medical':medical();break;case 'about':about();break;default:missing();}if(r==='concern'&&['pores','oil'].includes(id)&&parts[2])document.getElementById(parts[2])?.scrollIntoView({block:'start'});}
window.addEventListener('hashchange',route);
fetch('seed.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('data');return r.json();}).then(data=>{db=data;route();registerTools();}).catch(()=>display('<h1>情報を読み込めませんでした。</h1><p>しばらくしてから、ページを再読み込みしてください。</p>','読み込みエラー'));
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'navigate_ingredient',title:'成分の根拠を見る',description:'登録済み成分の根拠と注意の画面を開きます。診断や候補の生成は行いません。',inputSchema:{type:'object',properties:{ingredient_id:{type:'string',enum:db.ingredients.map(i=>i.id)}},required:['ingredient_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||typeof input.ingredient_id!=='string'||!find('ingredients',input.ingredient_id))throw new Error('登録済みの成分IDを指定してください。');location.hash='ingredient/'+input.ingredient_id;ingredient(input.ingredient_id);return {ingredient_id:input.ingredient_id,title:find('ingredients',input.ingredient_id).name_ja};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}

function tunemakers(){
 display(`${crumbs('チューンメーカーズの原液一覧')}<div class="eyebrow">TUNEMAKERS INDEX</div><h1>パッケージを見ながら、<br>原液シリーズを一覧で。</h1><p class="sub">メーカー公式の掲載商品です。容量違いも含みます。「効きそう」という印象と、確認できる商品情報を並べて見てください。</p><div class="notice"><p>チューンメーカーズの保湿が良かったという経験は、選ぶ手がかりになります。似た瓶や成分名だけで、同じ効果・相性があるとは判断できません。</p></div><label for="tm-search">商品名で絞る</label><br><input class="search" id="tm-search" type="search" placeholder="例：セラミド、EGF、ヒアルロン酸"><p class="metadata" id="tm-count" role="status"></p><div class="compare-bar"><span id="compare-count" role="status"></span><a class="button" href="#compare">選んだ商品を比較</a></div><div class="gallery" id="tm-list"></div><div class="section"><h2>たくさんの保湿商品から選ぶために</h2><p>「保湿」という一言だけで順位をつけず、本人が良かったと感じた商品、具体的な配合成分、商品自体の評価情報を並べて検討します。今の一覧は見比べるためのカタログです。</p><p class="sub">原液・200・EGFなどの名称やパッケージは、効果の強さの順位ではありません。商品ごとの注意と使い方は公式情報を確認してください。</p>${external('https://tunemakers.net/collections/%E5%8E%9F%E6%B6%B2','メーカー公式の原液一覧')}</div>`,'チューンメーカーズ原液一覧');
 const input=main.querySelector('#tm-search');input.value=tmQuery;const update=()=>{tmQuery=input.value;const q=input.value.normalize('NFKC').toLowerCase().trim();const items=db.tunemakers_catalog.filter(p=>p.name.normalize('NFKC').toLowerCase().includes(q));main.querySelector('#tm-count').textContent=items.length+'商品 · 公式情報確認：2026-10-03';main.querySelector('#tm-list').innerHTML=items.length?items.map(p=>`<article class="card tm-card">${p.image_url?`<img src="${E(p.image_url)}" alt="${E(p.name)}の公式パッケージ" loading="lazy" referrerpolicy="no-referrer" width="240" height="240">`:''}<h2>${E(p.name)}</h2><p class="metadata">${E(p.purpose)}</p><p class="metadata">商品自体の効果比較：未確認</p><button class="button secondary compare-pick" data-compare-id="${p.id}" aria-pressed="${comparisonIds.includes(p.id)}">${comparisonIds.includes(p.id)?'比較から外す':'比較に入れる'}</button><p>${external(p.url,'注記・商品情報を公式で見る')}</p></article>`).join(''):'<p class="empty">一致する商品がありません。</p>';};input.oninput=()=>{update();bindComparison();};update();bindComparison();
}

function bindComparison(){
 main.querySelector('#compare-count').textContent=comparisonIds.length+' / 3商品を選択';
 main.querySelectorAll('[data-compare-id]').forEach(button=>button.onclick=()=>{const id=button.dataset.compareId;if(comparisonIds.includes(id))comparisonIds=comparisonIds.filter(x=>x!==id);else if(comparisonIds.length<3)comparisonIds.push(id);else{main.querySelector('#compare-count').textContent='比較は3商品までです。選んだ商品を外して追加してください。';return;}button.setAttribute('aria-pressed',String(comparisonIds.includes(id)));button.textContent=comparisonIds.includes(id)?'比較から外す':'比較に入れる';main.querySelector('#compare-count').textContent=comparisonIds.length+' / 3商品を選択';});
}
function compareTunemakers(){
 const items=comparisonIds.map(id=>db.tunemakers_catalog.find(p=>p.id===id)).filter(Boolean);
 display(`${crumbs('選んだ原液を比較')}<h1>気になる商品を、並べて見る。</h1><p class="sub">パッケージや名称から受ける印象と、確認できる情報を分けて比較します。</p>${items.length?`<div class="gallery">${items.map(p=>`<article class="card tm-card"><img src="${E(p.image_url)}" alt="${E(p.name)}の公式パッケージ" width="240" height="240" referrerpolicy="no-referrer"><h2>${E(p.name)}</h2><dl class="compare-details"><dt>メーカーの配合目的</dt><dd>${E(p.purpose)}</dd><dt>商品自体の比較試験</dt><dd>このサイトでは未確認</dd><dt>自分との相性</dt><dd>まだ判断できません</dd><dt>確認元</dt><dd>メーカー公式 · ${E(p.source_checked_at)}</dd></dl>${external(p.url,'全成分・注記を公式で確認')}</article>`).join('')}</div><div class="notice"><p>商品名の数字や「原液」は、そのまま成分濃度や効果の強さを表しません。「セラミド200」の200はメーカーの通常品との比較表現で、成分が200%配合されている意味ではありません。</p></div><section class="section"><h2>選ぶ前に、ここを確認</h2><p>セラミドの種類、EGFの表記、誘導体かどうか、化粧品と医薬部外品の区分を、商品ごとの公式情報で確認します。配合成分の名前だけで、自分に合うかを確定しません。</p><p>チューンメーカーズの保湿が良かったという経験は参考になります。ただし、どの成分が良かったかや、シリーズ全体との相性までは分かりません。</p></section>`:'<div class="empty"><h2>比較する商品を選んでください。</h2><p>原液一覧の「比較に入れる」で3商品まで選べます。</p></div>'}<div class="actions">${a('#tunemakers','一覧へ戻る',true)}${items.length?'<button class="button secondary" id="clear-compare">選択をクリア</button>':''}</div>`,'原液の比較');
 const clear=main.querySelector('#clear-compare');if(clear)clear.onclick=()=>{comparisonIds=[];compareTunemakers();};
}

function discover(){
const seen=new Set();const items=db.tunemakers_catalog.filter(p=>{const name=p.name.replace(/（.*?）|\(.*?\)|[0-9]+\s*(?:mL|ml|g)/g,'').trim();if(seen.has(name))return false;seen.add(name);return true;}).slice(0,12);
display(`${crumbs('商品から探す')}<div class="eyebrow">FIND YOUR NEXT SKINCARE</div><h1>なんとなく、肌をきれいにしたい。</h1><p class="sub">まずは気になるパッケージから。<br>いつものブランドを見るか、肌の気になるところから探せます。</p><div class="options"><a class="option" href="#tunemakers"><b>使って良かったブランドから</b><br>チューンメーカーズの原液シリーズを見る</a><a class="option" href="#home"><b>肌の気になるところから</b><br>毛穴・くすみ・乾燥などから候補を探す</a></div><section class="section"><h2>いつものブランドで、ほかの商品も見てみる</h2><p class="metadata">チューンメーカーズ公式掲載順の一部です。相性や効果によるランキングではありません。</p><div class="gallery">${items.map(p=>`<article class="card tm-card"><img src="${E(p.image_url)}" alt="${E(p.name)}" width="240" height="240" loading="lazy" referrerpolicy="no-referrer"><h2>${E(p.name)}</h2><details><summary>成分・商品情報を確認</summary><p>${E(p.purpose)}</p>${external(p.url,'メーカー公式で見る')}</details></article>`).join('')}</div>${a('#tunemakers','原液シリーズをすべて見る',true)}</section>`,'商品から探す');
}

