function internationalCard(p){return `<article class="card"><img class="product-package" src="${E(p.image_url)}" alt="${E(p.name)}" loading="lazy" referrerpolicy="no-referrer"><span class="badge">海外メーカー情報 · 国内区分は未照合</span><h2>${E(p.name)}</h2><p>${E(p.brand)} · ${E(p.size)}</p><p class="metadata">${E(p.label_names.filter(t=>! /Glycerin|Hyaluron|グリセリン|ヒアルロン|セラミド/i.test(t)).join('、'))}</p>${p.product_type?`<p class="metadata">${E(p.product_type)}</p>`:''}${productComparison(p)}${p.cautions?.length?`<details><summary>使う前の注意</summary><ul>${p.cautions.map(t=>`<li>${E(t)}</li>`).join('')}</ul></details>`:''}<div class="actions"><a class="button" href="https://search.rakuten.co.jp/search/mall/${encodeURIComponent(p.brand+' '+p.name)}/" target="_blank" rel="noopener noreferrer">楽天でこの商品を探す（別タブ）</a></div><p class="metadata">検索結果の商品名・容量・日本向け処方を販売ページで確認してください。</p>${external(p.url,'成分・注意をメーカー公式で確認')}</article>`;}

