const dots=(points,color,r=2.5)=>points.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`).join('');
const marks={acne:dots([[53,62],[77,69],[67,46],[80,53]],'#e8a391',3),pores:dots([[59,65],[65,66],[70,65],[60,70],[69,70]],'#95a4b1',1.4),oil:'<path d="M65 44q-5 6 0 8q5-2 0-8" fill="#b4d8e0" stroke="none"/>',redness:'<ellipse cx="51" cy="66" rx="10" ry="6" fill="#efb6ad" stroke="none"/><ellipse cx="78" cy="66" rx="10" ry="6" fill="#efb6ad" stroke="none"/>',spots:dots([[49,62],[53,70],[77,61],[83,66]],'#c0a899',2.4),melasma:'<path d="M43 62q7-7 15 0l-2 7q-8 3-13-2m30-5q8-7 15 0l-1 6q-8 4-14 0" fill="#d5c0ac" stroke="none"/>',dry:'<path d="M48 65l4 3m-5 3l4 3m25-9l4 3m-5 3l4 3" stroke="#c4af9f" stroke-width="1.3"/>',sensitive:'<ellipse cx="50" cy="65" rx="8" ry="4" fill="#f2c8bd" stroke="none"/><path d="M93 34l3-6m1 12l7-2"/>',dull:'<path d="M43 68q21 12 43 0" stroke="#c9c1b6" stroke-width="6" opacity=".4"/>',lines:'<path d="M41 56l5 2m38-2l5-2M55 77q10 4 20 0" stroke="#b8a59b" stroke-width="1.3"/>',texture:dots([[48,65],[53,68],[48,71],[78,64],[83,68]],'#c9b7a9',1.5),overall:'<path d="M101 29v12m-6-6h12" stroke="#a6bd83"/>'};
return `<svg class="concern-art" viewBox="0 0 128 128" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><g stroke="#526b85" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M33 65C20 23 46 9 65 13c27-5 42 22 32 54l7 25q-14 10-29-2H47q-15 8-22-2Z" fill="#c3cdd2"/><path d="M49 89v10l-17 7q-12 5-13 19h92q-2-14-14-19l-18-7V89" fill="#ebc2b3"/><path d="M46 98q20 14 35 0l16 8q10 5 13 19H20q1-16 13-20Z" fill="#d5e5eb"/><path d="M41 47q0-19 23-24q11 13 24 18v25q-2 23-23 27q-22-3-24-26Z" fill="#fff8ef"/><path d="M41 49q-7-5-6 6q0 10 7 10m46-15q7-5 6 6q-1 9-6 9" fill="#fff8ef"/>${marks[id]||''}<path d="M48 51l7-2m19 0l7 2"/><ellipse cx="52" cy="58" rx="1.8" ry="2.5" fill="#526b85" stroke="none"/><ellipse cx="78" cy="58" rx="1.8" ry="2.5" fill="#526b85" stroke="none"/><path d="M65 59l-2 11h5m-9 8q6-${id==='overall'?'0':'4'} 12 0" fill="none"/><path d="M84 123l-7-24q-2-7 1-13l5-13q2-3 4-1l-3 14l5-16q2-3 4 0l-3 15l5-11q2-3 4 1l-4 19q-2 7-7 10l5 19" fill="#fff8ef"/></g></svg>`;
