function groupedProductSections(groups,heading,page){
 const key=p=>p.url||p.brand+'|'+p.name;
 const prepared=groups.map(([id,title,ingredient_ids,note])=>({id,title,ingredient_ids,note,ids:stateIngredientIds({ingredient_ids}),rows:stateProducts({ingredient_ids})}));
 const memberships=new Map();
 for(const group of prepared)for(const product of group.rows){const k=key(product);if(!memberships.has(k))memberships.set(k,{product,groups:[]});memberships.get(k).groups.push(group);}
 const common=[...memberships.values()].filter(entry=>entry.groups.length>1);
 const commonKeys=new Set(common.map(entry=>key(entry.product)));
 const card=(product,ids,types=[])=>catalogCard(product,ids).replace('<article class="card product-card">',`<article class="card product-card" data-grouped-product="${E(key(product))}">`).replace('</article>',`${types.length?`<p class="product-key-ingredients">${types.map(g=>`<a href="#concern/${page}/${g.id}">${E(g.title)}</a>`).join(' / ')}</p>`:''}<a class="product-rakuten" href="https://search.rakuten.co.jp/search/mall/${encodeURIComponent(product.brand+' '+product.name)}/" target="_blank" rel="noopener noreferrer">楽天でこの商品を探す</a></article>`);
 return `<section class="section"><h2>${E(heading)}</h2><section id="${page}-common" class="section" style="scroll-margin-top:24px"><h3>共通 <span class="metadata">${common.length}件</span></h3>${common.length?`<div class="cards">${common.map(entry=>card(entry.product,new Set(entry.groups.flatMap(g=>[...g.ids])),entry.groups)).join('')}</div>`:'<p>共通の商品はありません。</p>'}</section>${prepared.map(group=>{const rows=group.rows.filter(p=>!commonKeys.has(key(p))),hasCommon=group.rows.some(p=>commonKeys.has(key(p)));return `<section id="${group.id}" class="section" style="scroll-margin-top:24px"><h3>${E(group.title)} <span class="metadata">${group.ingredient_ids.length?rows.length+'件':''}</span></h3>${hasCommon?`<p><a href="#concern/${page}/${page}-common">共通の商品を見る</a></p>`:''}${!group.ingredient_ids.length&&group.note?`<p>${E(group.note)}</p>`:''}${rows.length?`<div class="cards">${rows.map(p=>card(p,group.ids)).join('')}</div>`:''}</section>`}).join('')}</section>`;
}

function ingredientProductSection(id){
 const state={ingredient_ids:Array.isArray(id)?id:[id]},ids=stateIngredientIds(state),rows=stateProducts(state,false);
 return `<section class="section ingredient-products"><h2>この成分を含む商品 <span class="metadata">${rows.length}件</span></h2>${rows.length?`<div class="cards">${rows.map(p=>catalogCard(p,ids).replace('<article class="card product-card">',`<article class="card product-card" data-ingredient-product="${E(p.id)}">`).replace('</article>',`<a class="product-rakuten" href="https://search.rakuten.co.jp/search/mall/${encodeURIComponent(p.brand+' '+p.name)}/" target="_blank" rel="noopener noreferrer">楽天でこの商品を探す</a></article>`)).join('')}</div>`:'<p>配合を確認した商品はまだ登録されていません。</p>'}</section>`;
}
function linkIngredientNames(html){
 if(!db?.ingredients)return html;
 const names=new Map();
 const preferred=['niacinamide','salicylic','azelaic','retinol','ceramide','tranexamic','vitamin_c'];
 const ordered=[...preferred.map(id=>find('ingredients',id)).filter(Boolean),...db.ingredients];
 for(const i of ordered){
  const terms=[i.name_ja,...(i.aliases||[])];
  for(const term of terms){if(typeof term!=='string'||term.length<4||!/[^\x00-\x7f]/.test(term)||/ビタミンC誘導体|ビタミンＣ誘導体/.test(term)||term.includes('※'))continue;const escaped=E(term);if(!names.has(escaped))names.set(escaped,i.id);}
 }
 names.set('AHA','aha');names.set('乳酸','inci_9799d9b8bac1');names.set('BHA','salicylic');names.set('ビタミンC','vitamin_c');names.set('ビタミンＣ','vitamin_c');
 const escapedTerms=[...names.keys()].sort((a,b)=>b.length-a.length).map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));
 const regex=new RegExp(escapedTerms.join('|'),'g');const stack=[];
 return html.split(/(<[^>]+>)/g).map(part=>{
  if(part.startsWith('<')){const close=part.match(/^<\/([a-z0-9]+)/i),open=part.match(/^<([a-z0-9]+)/i);if(close){const n=stack.lastIndexOf(close[1].toLowerCase());if(n>=0)stack.splice(n);}else if(open&&!/\/\s*>$/.test(part)&&!['img','input','br','hr','meta','link'].includes(open[1].toLowerCase()))stack.push(open[1].toLowerCase());return part;}
  if(stack.some(tag=>['a','button','script','style','h1','option','summary'].includes(tag)))return part;
  return part.replace(regex,(term,offset,text)=>{if((term==='ビタミンC'||term==='ビタミンＣ')&&text.slice(offset+term.length).startsWith('誘導体'))return term;if(term==='BHA'&&/[a-z]/i.test(text[offset-1]||''))return term;return `<a class="ingredient-inline-link" href="#ingredient/${E(names.get(term))}">${term}</a>`;});
 }).join('');
}

function ingredientGroupPage(id){const group=db.ingredient_groups.find(g=>g.id===id);if(!group)return missing();display(`${crumbs(group.name_ja)}<h1>${E(group.name_ja)}</h1><p>${E(group.description)}</p><h2>AHAに含まれる成分</h2><p>${group.ingredient_ids.map(id=>a('#ingredient/'+id,find('ingredients',id).name_ja)).join(' / ')}</p><h2>注意事項</h2><p>${E(group.caution)}</p><p>${external(group.source_url,'米国皮膚科学会：角質ケアの注意事項')}</p>${ingredientProductSection(group.ingredient_ids)}`,group.name_ja);}
